INSERT INTO `wp_posts` VALUES (4,1,'2026-09-22 01:57:16','2026-09-22 01:57:16','[ux_slider label=\"Hero Slider\" timer=\"6000\" auto_slide=\"true\" infinitive=\"true\" pause_hover=\"true\" draggable=\"true\" arrows=\"true\" bullets=\"true\" bullet_style=\"simple\" nav_style=\"simple\" nav_size=\"normal\" nav_color=\"light\" type=\"slide\" auto_height=\"false\" class=\"sa-hero-ux\" selectedattraction=\"0.08\" friction=\"0.35\" margin=\"0px\" margin__sm=\"0px\"]\r\n\r\n[section label=\"Slide 1 — Ổn định hôm nay\" class=\"sa-hero-slide\" height=\"660px\" padding=\"0px\" padding__sm=\"0px\" bg=\"43\" bg_size=\"large\" bg_pos=\"72% center\" bg_color=\"#003D35\" visibility=\"\"]\r\n\r\n[row style=\"collapse\" width=\"full-width\" v_align=\"middle\" class=\"sa-hero-slide__row row-full-width\"]\r\n\r\n[col span=\"6\" span__sm=\"12\" align=\"left\" class=\"sa-hero-slide__copy\"]\r\n<p class=\"sa-hero-slide__eyebrow\">Thiết bị điện công nghiệp</p>\r\n\r\n<h1 class=\"sa-hero-slide__title\">Ổn định hôm nay\r\nVững bước ngày mai</h1>\r\n<p class=\"sa-hero-slide__desc\">UPS, biến tần và pin công nghiệp cho doanh nghiệp, phòng máy và hệ thống kỹ thuật cần nguồn điện liên tục.</p>\r\n\r\n<div class=\"sa-hero-slide__actions\">[button text=\"Xem sản phẩm →\" color=\"white\" link=\"/san-pham/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--primary\"]\r\n[button text=\"Nhận tư vấn\" style=\"outline\" color=\"white\" link=\"/lien-he/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--ghost\"]</div>\r\n<ul class=\"sa-hero-slide__metrics\">\r\n 	<li><strong>15+</strong>Năm kinh nghiệm</li>\r\n 	<li><strong>500+</strong>Dự án triển khai</li>\r\n 	<li><strong>24/7</strong>Hỗ trợ kỹ thuật</li>\r\n 	<li><strong>Toàn quốc</strong>Phạm vi phục vụ</li>\r\n</ul>\r\n[/col]\r\n[col span=\"6\" span__sm=\"12\" class=\"sa-hero-slide__media\"]\r\n\r\n[ux_image id=\"43\" image_size=\"large\" class=\"sa-hero-slide__photo\"]\r\n<p class=\"sa-hero-slide__card\">Giải pháp nguồn điện tin cậy cho doanh nghiệp</p>\r\n[/col]\r\n\r\n[/row]\r\n\r\n[/section]\r\n\r\n[section label=\"Slide 2 — Bảo vệ hệ thống\" class=\"sa-hero-slide\" height=\"660px\" padding=\"0px\" padding__sm=\"0px\" bg=\"91\" bg_size=\"large\" bg_pos=\"70% center\" bg_color=\"#003D35\"]\r\n\r\n[row style=\"collapse\" width=\"full-width\" v_align=\"middle\" class=\"sa-hero-slide__row row-full-width\"]\r\n\r\n[col span=\"6\" span__sm=\"12\" align=\"left\" class=\"sa-hero-slide__copy\"]\r\n<p class=\"sa-hero-slide__eyebrow\">Giải pháp nguồn điện toàn diện</p>\r\n\r\n<h2 class=\"sa-hero-slide__title\">Bảo vệ hệ thống\r\nDuy trì hoạt động liên tục</h2>\r\n<p class=\"sa-hero-slide__desc\">Giải pháp UPS, biến tần và ắc quy cho trung tâm dữ liệu, nhà máy và tòa nhà cần nguồn điện không gián đoạn.</p>\r\n\r\n<div class=\"sa-hero-slide__actions\">[button text=\"Xem giải pháp →\" color=\"white\" link=\"/giai-phap/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--primary\"]\r\n[button text=\"Nhận tư vấn\" style=\"outline\" color=\"white\" link=\"/lien-he/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--ghost\"]</div>\r\n<ul class=\"sa-hero-slide__metrics\">\r\n 	<li><strong>An toàn</strong>Bảo vệ thiết bị</li>\r\n 	<li><strong>Hiệu quả</strong>Tối ưu vận hành</li>\r\n 	<li><strong>Bền bỉ</strong>Nguồn ổn định</li>\r\n 	<li><strong>Chuyên nghiệp</strong>Hỗ trợ 24/7</li>\r\n</ul>\r\n[/col]\r\n[col span=\"6\" span__sm=\"12\" class=\"sa-hero-slide__media\"]\r\n\r\n[ux_image id=\"91\" image_size=\"large\" class=\"sa-hero-slide__photo\"]\r\n<p class=\"sa-hero-slide__card\">Giải pháp hạ tầng điện cho trung tâm dữ liệu</p>\r\n[/col]\r\n\r\n[/row]\r\n\r\n[/section]\r\n\r\n[section label=\"Slide 3 — Mọi quy mô\" class=\"sa-hero-slide\" height=\"660px\" padding=\"0px\" padding__sm=\"0px\" bg=\"51\" bg_size=\"large\" bg_pos=\"68% center\" bg_color=\"#003D35\"]\r\n\r\n[row style=\"collapse\" width=\"full-width\" v_align=\"middle\" class=\"sa-hero-slide__row row-full-width\"]\r\n\r\n[col span=\"6\" span__sm=\"12\" align=\"left\" class=\"sa-hero-slide__copy\"]\r\n<p class=\"sa-hero-slide__eyebrow\">Đồng hành cùng doanh nghiệp</p>\r\n\r\n<h2 class=\"sa-hero-slide__title\">Giải pháp phù hợp\r\ncho mọi quy mô</h2>\r\n<p class=\"sa-hero-slide__desc\">Từ doanh nghiệp vừa và nhỏ đến nhà máy công nghiệp, THỊNH PHÁT tư vấn và triển khai nguồn điện phù hợp.</p>\r\n\r\n<div class=\"sa-hero-slide__actions\">[button text=\"Xem dự án →\" color=\"white\" link=\"/du-an/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--primary\"]\r\n[button text=\"Nhận tư vấn\" style=\"outline\" color=\"white\" link=\"/lien-he/\" class=\"sa-hero-slide__btn sa-hero-slide__btn--ghost\"]</div>\r\n<ul class=\"sa-hero-slide__metrics\">\r\n 	<li><strong>Tư vấn</strong>Chuyên sâu</li>\r\n 	<li><strong>Triển khai</strong>Nhanh, đúng việc</li>\r\n 	<li><strong>Hậu mãi</strong>Tận tâm</li>\r\n 	<li><strong>Đầu tư</strong>Hiệu quả rõ</li>\r\n</ul>\r\n[/col]\r\n[col span=\"6\" span__sm=\"12\" class=\"sa-hero-slide__media\"]\r\n\r\n[ux_image id=\"51\" image_size=\"large\" class=\"sa-hero-slide__photo\"]\r\n<p class=\"sa-hero-slide__card\">Thiết bị điện công nghiệp đáng tin cậy</p>\r\n[/col]\r\n\r\n[/row]\r\n\r\n[/section]\r\n\r\n[/ux_slider]\r\n\r\n[sa_home_catalog]\r\n\r\n[section label=\"About\" class=\"sa-section sa-about\" padding=\"0px\" padding__sm=\"0px\"]\r\n\r\n[row style=\"large\" width=\"custom\" custom_width=\"1240px\" v_align=\"middle\" class=\"sa-about__row\"]\r\n\r\n[col span=\"6\" span__sm=\"12\" class=\"sa-about-media\"]\r\n<div class=\"sa-about-visual\" role=\"img\" aria-label=\"Hệ thống thiết bị điện công nghiệp\">\r\n<div class=\"sa-about-visual__photo\"><img src=\"https://thinhphattsc.com/wp-content/uploads/2026/09/thinhphat-about-facility-1024x768.jpg\" alt=\"Hệ thống thiết bị điện công nghiệp THỊNH PHÁT\" width=\"1200\" height=\"900\" /></div>\r\n</div>\r\n[/col]\r\n[col span=\"6\" span__sm=\"12\" class=\"sa-about-copy\"]\r\n<div class=\"sa-section-head\">\r\n<p class=\"sa-eyebrow\">VỀ THỊNH PHÁT</p>\r\n\r\n<h2 class=\"sa-title sa-about__title\">GIẢI PHÁP THIẾT BỊ ĐIỆN\r\n<span class=\"sa-about__title-em\">CHO HỆ THỐNG VẬN HÀNH ỔN ĐỊNH</span></h2>\r\n</div>\r\n<p class=\"sa-lead sa-about__desc\">THỊNH PHÁT cung cấp các giải pháp UPS, biến tần, pin và ắc quy phục vụ doanh nghiệp, nhà máy, hệ thống kỹ thuật và các ứng dụng cần nguồn điện ổn định.</p>\r\n\r\n<ul class=\"sa-about__points\">\r\n 	<li>Giải pháp phù hợp nhu cầu</li>\r\n 	<li>Tư vấn kỹ thuật</li>\r\n 	<li>Hỗ trợ tận tâm</li>\r\n</ul>\r\n<div class=\"sa-actions sa-about__actions\"><a class=\"sa-btn sa-btn--solid\" href=\"/gioi-thieu/\">Tìm hiểu thêm</a></div>\r\n[/col]\r\n\r\n[/row]\r\n\r\n[/section]\r\n\r\n[section label=\"Why Choose Us\" class=\"sa-section sa-section--alt sa-why\" padding=\"0px\" padding__sm=\"0px\"]\r\n\r\n[row width=\"custom\" custom_width=\"1240px\"]\r\n\r\n[col span=\"12\" span__sm=\"12\"]\r\n<div class=\"sa-section-head is-center\">\r\n<p class=\"sa-eyebrow\">Lợi thế</p>\r\n\r\n<h2 class=\"sa-title\">VÌ SAO LỰA CHỌN THỊNH PHÁT?</h2>\r\n</div>\r\n<div class=\"sa-why__grid\"><article class=\"sa-why-card\">\r\n<div class=\"sa-why-card__top\"><span class=\"sa-why-card__num\">01</span>\r\n&nbsp;\r\n\r\n</div>\r\n<h3 class=\"sa-why-card__title\">GIẢI PHÁP PHÙ HỢP</h3>\r\n<p class=\"sa-why-card__text\">Tư vấn thiết bị theo nhu cầu và đặc điểm hệ thống.</p>\r\n\r\n</article><article class=\"sa-why-card\">\r\n<div class=\"sa-why-card__top\"><span class=\"sa-why-card__num\">02</span>\r\n&nbsp;\r\n\r\n</div>\r\n<h3 class=\"sa-why-card__title\">HỖ TRỢ KỸ THUẬT</h3>\r\n<p class=\"sa-why-card__text\">Đồng hành trong quá trình lựa chọn và sử dụng thiết bị.</p>\r\n\r\n</article><article class=\"sa-why-card\">\r\n<div class=\"sa-why-card__top\"><span class=\"sa-why-card__num\">03</span>\r\n&nbsp;\r\n\r\n</div>\r\n<h3 class=\"sa-why-card__title\">DANH MỤC ĐA DẠNG</h3>\r\n<p class=\"sa-why-card__text\">UPS, biến tần, pin và ắc quy cho nhiều ứng dụng.</p>\r\n\r\n</article><article class=\"sa-why-card\">\r\n<div cl